<span style="font-size:10px;color:#666;line-height:1.4">Hover an arrow for its meaning, click for a short explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 600, H = 520;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var NAVY = '#1F4E79', ORANGE = '#E8722C', TEAL = '#149490', RED = '#C64257',
      PURPLE = '#7B3FA0', GRAY = '#B5B5B5';

  var ANG = 17 * Math.PI / 180;
  var DX = Math.cos(ANG), DY = -Math.sin(ANG);     // unit direction of v (screen coords)
  var PX = -DY, PY = DX;                           // perpendicular (points up-left-ish? see use)
  // perpendicular "up" side (above the line) and "down" side
  var UPX = DY, UPY = -DX;      // (-0.292, -0.956) -> up-left
  var DNX = -DY, DNY = DX;      // ( 0.292,  0.956) -> down-right

  var L_MAIN = 148;   // length of v in the stacked (faithful) layout
  var L_WORK = 62;    // length of v in the interactive workbench
  var L_OVER = 90;    // length of v in the common-tail overlay

  var kVal = 1, overlay = false;

  /* ---------- drawing helpers ---------- */
  function lbl(g, str, x, y, color, size, anchor, italic) {
    var t = g.plain(str);
    t.font({
      family: 'Georgia, "Times New Roman", serif',
      size: size,
      style: italic ? 'italic' : 'normal',
      weight: italic ? 'bold' : 'normal',
      anchor: anchor || 'start'
    });
    t.attr({ x: x, y: y, 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    t.fill(color);
    return t;
  }

  function arrow(parent, tx, ty, hx, hy, color, w) {
    var g = parent.group();
    var dx = hx - tx, dy = hy - ty, len = Math.hypot(dx, dy);
    if (len < 1.2) {
      g.circle(9).center(tx, ty).fill('none').stroke({ color: color, width: 2 });
      return g;
    }
    var ux = dx / len, uy = dy / len;
    var hl = Math.max(8, Math.min(16, len * 0.2));
    var bx = hx - ux * hl, by = hy - uy * hl;
    g.line(tx, ty, bx, by).stroke({ color: color, width: w, linecap: 'butt' });
    var hw = hl * 0.42;
    g.polygon([[hx, hy], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
    var hit = g.line(tx, ty, hx, hy).stroke({ color: '#ffffff', width: 18, opacity: 0 });
    hit.attr('pointer-events', 'stroke');
    return g;
  }

  function dot(parent, x, y, r, color) {
    return parent.circle((r || 4.2) * 2).center(x, y).fill(color || '#000');
  }

  function interactive(g, tip, title, body) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(tip, e); });
    g.on('mouseleave', function () { hideTooltip(); });
    g.on('click', function () { showPopup(title, body); });
    return g;
  }

  /* ---------- content ---------- */
  var STACK = [
    { k: 3, c: NAVY, tail: [32, 155], lab: '3v', lx: -4, ly: -12, an: 'middle',
      tip: '3v — three times as long as v, same direction',
      body: 'Multiplying by 3 stretches the arrow to three times its length. The slope (direction) is untouched, so 3v lies on the same line of action as v.' },
    { k: 1, c: ORANGE, tail: [32, 240], lab: 'v', lx: -8, ly: -14, an: 'middle',
      tip: 'v — the original vector',
      body: 'This is the reference vector v. Its length is its magnitude and its slope is its direction; every other arrow here is a scalar multiple of it.' },
    { k: 0.5, c: TEAL, tail: [32, 315], lab: '½v', lx: -6, ly: -14, an: 'middle',
      tip: '½v — half as long as v, same direction',
      body: 'A scalar between 0 and 1 shrinks the vector. Half of v is half as long but still points up and to the right, exactly parallel to v.' },
