PREVIOUS GENERATED PAYLOAD (edit this; do NOT output full HTML):
<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:bold;font-size:12px">Scalar multiples of a vector</span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;color:#333;border-left:3px solid #7B3FA0;padding-left:6px"></span>
