</label>
<label>Scalar multiplier k: <output id="scalarKVal">1.0</output>
  <input id="scalarKInput" type="range" min="-3" max="3" step="0.1" value="1"
    oninput="document.getElementById('scalarKVal').value=(+this.value).toFixed(1);update_scalarK(+this.value)">
</label>
