<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 600, H = 520;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var NAVY = '#1F4E79', ORANGE = '#E8722C', TEAL = '#149490', RED = '#C64257',
      PURPLE = '#7B3FA0', GRAY = '#B5B5B5';

  var ANG = 17 * Math.PI / 180;
  var DX = Math.cos(ANG), DY = -Math.sin(ANG);     // unit direction of v (screen coords)
  var PX = -DY, PY = DX;                           // perpendicular (points up-left-ish? see use)
  // perpendicular "up" side (above the line) and "down" side
  var UPX = DY, UPY = -DX;      // (-0.292, -0.956) -> up-left
  var DNX = -DY, DNY = DX;      // ( 0.292,  0.956) -> down-right

  var L_MAIN = 148;   // length of v in the stacked (faithful) layout
  var L_WORK = 62;    // length of v in the interactive workbench
  var L_OVER = 90;    // length of v in the common-tail overlay

  var kVal = 1, overlay = false;

  /* ---------- drawing helpers ---------- */
  function lbl(g, str, x, y, color, size, anchor, italic) {
    var t = g.plain(str);
    t.font({
      family: 'Georgia, "Times New Roman", serif',
      size: size,
      style: italic ? 'italic' : 'normal',
      weight: italic ? 'bold' : 'normal',
      anchor: anchor || 'start'
    });
    t.attr({ x: x, y: y, 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    t.fill(color);
    return t;
  }

  function arrow(parent, tx, ty, hx, hy, color, w) {
    var g = parent.group();
    var dx = hx - tx, dy = hy - ty, len = Math.hypot(dx, dy);
    if (len < 1.2) {
      g.circle(9).center(tx, ty).fill('none').stroke({ color: color, width: 2 });
      return g;
    }
    var ux = dx / len, uy = dy / len;
    var hl = Math.max(8, Math.min(16, len * 0.2));
    var bx = hx - ux * hl, by = hy - uy * hl;
    g.line(tx, ty, bx, by).stroke({ color: color, width: w, linecap: 'butt' });
    var hw = hl * 0.42;
    g.polygon([[hx, hy], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
    var hit = g.line(tx, ty, hx, hy).stroke({ color: '#ffffff', width: 18, opacity: 0 });
    hit.attr('pointer-events', 'stroke');
    return g;
  }

  function dot(parent, x, y, r, color) {
    return parent.circle((r || 4.2) * 2).center(x, y).fill(color || '#000');
  }

  function interactive(g, tip, title, body) {
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(tip, e); });
    g.on('mouseleave', function () { hideTooltip(); });
    g.on('click', function () { showPopup(title, body); });
    return g;
  }

  /* ---------- content ---------- */
  var STACK = [
    { k: 3, c: NAVY, tail: [32, 155], lab: '3v', lx: -4, ly: -12, an: 'middle',
      tip: '3v — three times as long as v, same direction',
      body: 'Multiplying by 3 stretches the arrow to three times its length. The slope (direction) is untouched, so 3v lies on the same line of action as v.' },
    { k: 1, c: ORANGE, tail: [32, 240], lab: 'v', lx: -8, ly: -14, an: 'middle',
      tip: 'v — the original vector',
      body: 'This is the reference vector v. Its length is its magnitude and its slope is its direction; every other arrow here is a scalar multiple of it.' },
    { k: 0.5, c: TEAL, tail: [32, 315], lab: '½v', lx: -6, ly: -14, an: 'middle',
      tip: '½v — half as long as v, same direction',
      body: 'A scalar between 0 and 1 shrinks the vector. Half of v is half as long but still points up and to the right, exactly parallel to v.' },
    { k: -1, c: RED, tail: [190, 385], lab: '−v', lx: 16, ly: 5, an: 'start', atTail: true,
      tip: '−v — same length as v, opposite direction',
      body: 'A negative scalar reverses the heading. −v has exactly the same magnitude as v but points the opposite way along the same line.' }
  ];

  function dirText(k) {
    if (k > 0.03) return 'direction: same as v';
    if (k < -0.03) return 'direction: opposite to v';
    return 'zero vector — no direction';
  }

  function renderReadout(cx, y) {
    var g = draw.group();
    lbl(g, 'k = ' + kVal.toFixed(1), cx, y, '#222', 13, 'middle', false);
    lbl(g, '| k v | = ' + Math.abs(kVal).toFixed(2) + ' × | v |', cx, y + 17, '#222', 13, 'middle', false);
    lbl(g, dirText(kVal), cx, y + 34,
      kVal > 0.03 ? '#1a7f37' : (kVal < -0.03 ? '#b3261e' : '#666'), 12, 'middle', false);
  }

  function renderLegend() {
    var g = draw.group();
    var rows = [
      [NAVY, '3v'], [ORANGE, 'v'], [TEAL, '½v'], [RED, '−v'], [PURPLE, 'k v  (slider)']
    ];
    for (var i = 0; i < rows.length; i++) {
      var y = 24 + i * 15;
      g.line(20, y - 4, 42, y - 4).stroke({ color: rows[i][0], width: 3, linecap: 'round' });
      lbl(g, rows[i][1], 48, y, '#444', 11, 'start', true);
    }
  }

  function renderWorkbench(ox, oy, scale) {
    var g = draw.group();
    // faint infinite line of action
    var ln = g.line(ox - DX * 185, oy - DY * 185, ox + DX * 185, oy + DY * 185)
      .stroke({ color: '#c9c9c9', width: 1, dasharray: '5,5' });
    interactive(g.group().add(ln), 'line of action — every multiple of v lands here',
      'Line of action',
      'No matter which scalar you pick, the tip of k·v stays on this single dashed line through the tail. Scalar multiplication moves you along the line, never off it.');
    // gray reference copy of v
    var rg = arrow(g, ox, oy, ox + DX * scale, oy + DY * scale, GRAY, 2);
    interactive(rg, 'reference copy of v (length 1·|v|)', 'Reference v',
      'This gray arrow is always one copy of v. Compare the purple arrow against it to read off how many times longer or shorter k·v is.');
    lbl(g, 'v', ox + DX * scale + DNX * 15, oy + DY * scale + DNY * 15 + 4, '#999', 12, 'middle', true);
    // interactive k v
    var hx = ox + DX * scale * kVal, hy = oy + DY * scale * kVal;
    var ag = arrow(g, ox, oy, hx, hy, PURPLE, 3.4);
    interactive(ag, 'k v  with k = ' + kVal.toFixed(1), 'k v',
      'Length is |k| times |v| (' + Math.abs(kVal).toFixed(2) + '×), and the sign of k decides which of the two directions along the line you travel.');
    dot(g, ox, oy, 4.2, '#000');
    var side = (kVal >= 0) ? [DNX, DNY] : [UPX, UPY];
    if (Math.abs(kVal) < 0.03) {
      lbl(g, '0', ox + 12, oy - 12, PURPLE, 14, 'start', true);
    } else {
      lbl(g, 'k v', hx + side[0] * 17, hy + side[1] * 17 + 4, PURPLE, 14, 'middle', true);
    }
  }

  function renderStacked() {
    for (var i = 0; i < STACK.length; i++) {
      var s = STACK[i];
      var tx = s.tail[0], ty = s.tail[1];
      var hx = tx + DX * L_MAIN * s.k, hy = ty + DY * L_MAIN * s.k;
      var g = draw.group();
      var a = arrow(g, tx, ty, hx, hy, s.c, 3);
      dot(g, tx, ty, 4.2, '#000');
      interactive(a, s.tip, s.lab, s.body);
      var lxp = s.atTail ? tx : hx, lyp = s.atTail ? ty : hy;
      lbl(draw, s.lab, lxp + s.lx, lyp + s.ly, '#111', 15, s.an, true);
    }
    renderWorkbench(410, 355, L_WORK);
    renderReadout(410, 442);
  }

  function renderOverlay() {
    var T = [290, 290];
    var g0 = draw.group();
    var ln = g0.line(T[0] - DX * 280, T[1] - DY * 280, T[0] + DX * 300, T[1] + DY * 300)
      .stroke({ color: '#bfbfbf', width: 1.2, dasharray: '6,5' });
    interactive(g0, 'the single line of action shared by every multiple of v',
      'One line of action',
      'With all the tails pinned to one point, the heads of 3v, v, ½v, −v and k·v all fall on this one dashed line. |k| sets how far along, the sign of k sets which way.');

    var items = [
      { k: 3, c: NAVY, lab: '3v', tip: '3v — three times as far along the line' },
      { k: 1, c: ORANGE, lab: 'v', tip: 'v — the original vector' },
      { k: 0.5, c: TEAL, lab: '½v', tip: '½v — half as far along the line' },
      { k: -1, c: RED, lab: '−v', tip: '−v — same distance, other direction' }
    ];
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      var hx = T[0] + DX * L_OVER * it.k, hy = T[1] + DY * L_OVER * it.k;
      var g = draw.group();
      var a = arrow(g, T[0], T[1], hx, hy, it.c, 3);
      interactive(a, it.tip, it.lab,
        'Drawn from the shared tail, ' + it.lab + ' still ends on the same dashed line. Only its distance from the tail (|k|·|v|) and its side of the tail change.');
      var sd = it.k >= 0 ? [UPX, UPY] : [DNX, DNY];
      lbl(draw, it.lab, hx + sd[0] * 19, hy + sd[1] * 19 + 4, '#111', 14, 'middle', true);
    }

    var kx = T[0] + DX * L_OVER * kVal, ky = T[1] + DY * L_OVER * kVal;
    var gk = draw.group();
    var ak = arrow(gk, T[0], T[1], kx, ky, PURPLE, 3.6);
    interactive(ak, 'k v  with k = ' + kVal.toFixed(1), 'k v',
      'Slide k and watch the purple head slide along the dashed line — through the tail at k = 0 and out the other side for negative k.');
    dot(draw, T[0], T[1], 4.6, '#000');
    if (Math.abs(kVal) < 0.03) {
      lbl(draw, '0', T[0] + 13, T[1] - 13, PURPLE, 14, 'start', true);
    } else {
      var sk = kVal >= 0 ? [DNX, DNY] : [UPX, UPY];
      lbl(draw, 'k v', kx + sk[0] * 19, ky + sk[1] * 19 + 4, PURPLE, 14, 'middle', true);
    }
    renderReadout(300, 442);
  }

  function render() {
    draw.clear();
    draw.rect(W, H).fill('#ffffff');
    if (overlay) renderOverlay(); else renderStacked();
    renderLegend();
  }

  /* ---------- controls ---------- */
  window.update_scalarK = function (v) { kVal = +v; render(); };
  window.toggle_layoutMode = function (on) { overlay = !!on; render(); };

  /* ---------- demo steps ---------- */
  var STEPS = [
    { title: 'The original vector v',
      narration: 'Start with the orange vector v. Its length is the magnitude and its slope is the direction; every other arrow in the figure is built from this one.',
      state: { scalarK: 1, layoutMode: 'Stacked' } },
    { title: 'Stretching: k = 3',
      narration: 'Drag k to 3 and the arrow becomes three times as long while pointing exactly the same way — matching the navy 3v at the top.',
      state: { scalarK: 3, layoutMode: 'Stacked' } },
    { title: 'Shrinking: k = ½',
      narration: 'Now set k to 0.5. The arrow halves in length but still heads up and to the right — this is the teal ½v.',
      state: { scalarK: 0.5, layoutMode: 'Stacked' } },
    { title: 'Collapsing at k = 0',
      narration: 'Slide k to 0 and the arrow shrinks to a single point at the tail: the zero vector, with no length and no meaningful direction.',
      state: { scalarK: 0, layoutMode: 'Stacked' } },
    { title: 'Reversing: k = −1',
      narration: 'Push k past zero to −1. The arrow reappears with the same length as v but now points down and to the left — the red −v.',
      state: { scalarK: -1, layoutMode: 'Stacked' } },
    { title: 'All multiples share one line',
      narration: 'Switch to the common-tail overlay: every multiple of v, positive or negative, has its head on the same dashed line through the tail. Scalar multiplication never changes the line of action, only where you land on it.',
      state: { scalarK: -2, layoutMode: 'Common tail overlay' } }
  ];
  var cur = 0;

  function setStep(i) {
    cur = Math.max(0, Math.min(STEPS.length - 1, i));
    var s = STEPS[cur];
    var sl = document.getElementById('scalarKInput');
    var cb = document.getElementById('layoutModeInput');
    sl.value = s.state.scalarK;
    document.getElementById('scalarKVal').value = (+s.state.scalarK).toFixed(1);
    cb.checked = (s.state.layoutMode === 'Common tail overlay');
    kVal = +s.state.scalarK;
    overlay = cb.checked;
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + STEPS.length + ' · ' + s.title;
    render();
  }
  window.prevStep = function () { setStep(cur - 1); };
  window.nextStep = function () { setStep(cur + 1); };

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

